// ==========================================
// 注文メール自動抽出＆書庫登録スクリプト
// ==========================================

function processOrderEmails() {
  const DRY_RUN = true; // テスト時は true にしてスプレッドシートへの書き込みとラベル付与を無効化します

  const PROCESSED_LABEL_NAME = '書庫登録済';
  let processedLabel;
  if (!DRY_RUN) {
    processedLabel = GmailApp.getUserLabelByName(PROCESSED_LABEL_NAME);
    if (!processedLabel) {
      processedLabel = GmailApp.createLabel(PROCESSED_LABEL_NAME);
    }
  }

  // テスト時 (DRY_RUN=true) はラベルを除外せず、最近の注文メールを何度でもテストできるようにします
  const query = DRY_RUN 
      ? '(from:auto-confirm@amazon.co.jp OR from:digital-no-reply@amazon.co.jp OR from:send_only@value-books.jp OR from:info@bookoffonline.jp)'
      : '(from:auto-confirm@amazon.co.jp OR from:digital-no-reply@amazon.co.jp OR from:send_only@value-books.jp OR from:info@bookoffonline.jp) -label:' + PROCESSED_LABEL_NAME;

  const threads = GmailApp.search(query, 0, 10);

  if (threads.length === 0) {
    Logger.log("新しい注文メールはありませんでした。");
    return;
  }

  const sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();

  for (let i = 0; i < threads.length; i++) {
    const thread = threads[i];
    const messages = thread.getMessages();
    let addedCount = 0;

    for (let j = 0; j < messages.length; j++) {
      const msg = messages[j];
      const sender = msg.getFrom();
      const body = msg.getPlainBody();
      let htmlBody = msg.getBody();

      let books = []; // { title: '', isbn: '', isAmazonB0: false }

      // ==========================================
      // 1. Amazon (紙 ＆ Kindle)
      // ==========================================
      if (sender.indexOf('amazon.co.jp') !== -1) {

        // 【重要】おすすめ商品（関連商品）のASINを巻き込まないように、本文の下部をカットする
        const cutPhrases = ['お客様が閲覧した商品に関連する商品', 'おすすめ商品', 'この商品を買った人はこんな商品も', '関連商品'];
        for (let c = 0; c < cutPhrases.length; c++) {
          let cutIndex = htmlBody.indexOf(cutPhrases[c]);
          if (cutIndex !== -1) {
            htmlBody = htmlBody.substring(0, cutIndex);
          }
        }

        // AmazonはURLからASIN/ISBN-10を抽出するのが最も確実 (暗号化URL内の %2F も考慮)
        const asinRegex = /(?:dp|product|ASIN)(?:\/|%2F)([A-Z0-9]{10})/gi;
        let asins = [];
        let match;
        while ((match = asinRegex.exec(htmlBody)) !== null) {
          if (asins.indexOf(match[1]) === -1) asins.push(match[1]);
        }

        Logger.log("Amazonメールを処理: " + msg.getSubject() + " | 抽出ASIN: " + asins.join(", "));

        for (let k = 0; k < asins.length; k++) {
          let asin = asins[k];
          let title = '';

          // HTML本文から、このASINを含む <a> タグのテキスト（タイトル）を抽出を試みる
          let titleRegex = new RegExp(asin + '[^>]*>\\s*([^<]+?)\\s*<\\/a>', 'i');
          let m = htmlBody.match(titleRegex);
          if (m && m[1] && m[1].indexOf('<img') === -1 && m[1].trim().length > 0) {
             title = m[1].trim();
             try { title = decodeURIComponent(title); } catch(e){}
             title = title.replace(/[\r\n]+/g, ' ').trim();
          }

          if (asin.match(/^4[0-9]{9}$/)) {
            Logger.log(" -> 紙の本として判定: " + asin + (title ? " (" + title + ")" : ""));
            books.push({ isbn: convertIsbn10To13(asin), title: title, isAmazonB0: false });
          } else if (asin.match(/^B0/)) {
            Logger.log(" -> KindleまたはAmazon商品: " + asin);
            if (title && title.indexOf('ヘルプ') === -1 && title.indexOf('税金') === -1) {
               Logger.log("    -> タイトル抽出成功: " + title);
               // B0の商品はTシャツや家電の可能性もあるため、フラグを立てて後でNDLで検証する
               books.push({ isbn: '', title: title, isAmazonB0: true });
            } else {
               Logger.log("    -> タイトルが抽出できなかったためスキップします");
            }
          }
        }
      }

      // ==========================================
      // 2. バリューブックス
      // ==========================================
      else if (sender.indexOf('value-books.jp') !== -1) {
        let inOrderList = false;
        const lines = body.split('\n');
        for (let l = 0; l < lines.length; l++) {
          let line = lines[l].trim();
          if (line === 'ご注文商品') {
            inOrderList = true;
            continue;
          }
          if (inOrderList) {
            if (line.indexOf('※') === 0 || line === '商品配送先') break;
            if (line === '') continue; // 空行は無視
            let cleanTitle = line.replace(/全\d+巻.*セット/g, '').replace(/【中古】/g, '').trim();
            if (cleanTitle) books.push({ title: cleanTitle, isbn: '', isAmazonB0: false });
          }
        }
      }

      // ==========================================
      // 3. ブックオフオンライン
      // ==========================================
      else if (sender.indexOf('bookoffonline.jp') !== -1) {
        const lines = body.split('\n');
        for (let l = 0; l < lines.length; l++) {
          let line = lines[l].trim();
          if (line.indexOf('【中古】') !== -1 && line.indexOf('ご注文点数') !== -1) {
            let cleanTitle = line.replace(/【中古】/g, '')
                                 .replace(/\(￥[0-9,]+\).*$/g, '')
                                 .trim();
            if (cleanTitle) books.push({ title: cleanTitle, isbn: '', isAmazonB0: false });
          }
        }
      }

      // ==========================================
      // 抽出した本をNDLで検索してシートに登録
      // ==========================================
      if (books.length === 0) {
        Logger.log(" -> [スキップ] このメールからは本が抽出されませんでした。");
      }

      for (let k = 0; k < books.length; k++) {
        let b = books[k];
        Logger.log("抽出アイテム: " + (b.isbn || b.title));

        let ndlData = searchNdlForEmail(b.isbn, b.title);

        if (ndlData.found) {
          // NDLでヒットした場合（確実に本である）
          let finalTitle = ndlData.title || b.title;
          let finalAuthor = ndlData.author || '';
          let finalPub = ndlData.publisher || '';
          let finalYear = ndlData.year || '';
          let finalIsbn = ndlData.isbn || b.isbn || '';

          if (!DRY_RUN) sheet.appendRow([finalTitle, finalAuthor, finalPub, finalYear, finalIsbn, '読みたい']);
          addedCount++;
          Logger.log("書庫に追加しました(NDLヒット): " + finalTitle + (DRY_RUN ? " (※テストモード)" : ""));

        } else {
          // NDLでヒットしなかった場合
          if (b.isAmazonB0) {
            // AmazonのB0系（Kindleか家電等）でNDLに無いなら、本ではない（Tシャツやモニター）と判断してスキップ
            Logger.log(" -> [スキップ] NDLに存在しないAmazon商品（本ではない可能性大）: " + b.title);
          } else {
            // バリューブックス等やAmazonの紙の本（ISBNあり）なら、NDLになくても本なので登録する
            let finalTitle = b.title || "不明なタイトル";
            if (!DRY_RUN) sheet.appendRow([finalTitle, '', '', '', b.isbn || '', '読みたい']);
            addedCount++;
            Logger.log("書庫に追加しました(NDL未ヒットだが本として強制追加): " + finalTitle + (DRY_RUN ? " (※テストモード)" : ""));
          }
        }
      }
    }

    // 処理が完了したスレッドにラベルを付けて次回からスキップする
    if (!DRY_RUN) {
      thread.addLabel(processedLabel);
    }
    Logger.log("スレッド処理完了 (追加数: " + addedCount + ")\n------------------------");
  }
}

// ---------------------------------------------------
// ヘルパー関数群
// ---------------------------------------------------

function convertIsbn10To13(isbn10) {
  if (isbn10.length !== 10) return isbn10;
  var isbn13 = "978" + isbn10.substring(0, 9);
  var sum = 0;
  for (var i = 0; i < 12; i++) {
    sum += parseInt(isbn13.charAt(i)) * (i % 2 === 0 ? 1 : 3);
  }
  var checkDigit = (10 - (sum % 10)) % 10;
  return isbn13 + checkDigit;
}

function searchNdlForEmail(isbn, title) {
  var result = { title: '', author: '', publisher: '', year: '', isbn: '', found: false };
  var query = isbn ? "isbn=" + isbn : "title=\"" + encodeURIComponent(title) + "\"";
  var url = "https://ndlsearch.ndl.go.jp/api/sru?operation=searchRetrieve&recordPacking=xml&query=" + query;

  try {
    var res = UrlFetchApp.fetch(url, {muteHttpExceptions: true});
    if (res.getResponseCode() === 200) {
      var xmlStr = res.getContentText();
      var titleMatch = xmlStr.match(/<dc:title[^>]*>([^<]+)<\/dc:title>/);
      var creatorMatch = xmlStr.match(/<dc:creator[^>]*>([^<]+)<\/dc:creator>/);
      var pubMatch = xmlStr.match(/<dc:publisher[^>]*>([^<]+)<\/dc:publisher>/);
      var dateMatch = xmlStr.match(/<dc:date[^>]*>([^<]+)<\/dc:date>/);
      var identifierMatch = xmlStr.match(/<dc:identifier[^>]*xsi:type="dcndl:ISBN"[^>]*>([^<]+)<\/dc:identifier>/);

      if (titleMatch || identifierMatch) {
        result.found = true;
      }

      if (titleMatch) result.title = titleMatch[1];
      if (creatorMatch) result.author = creatorMatch[1];
