// ==========================================
// 1. Amazon (紙 ＆ Kindle)
// ==========================================
if (sender.indexOf('amazon.co.jp') !== -1) {
  let orderedTitles = [];
  let lines = body.split('\n');

  // プレーンテキストから実際に「注文された（数量や商品名表記がある）」タイトルだけを抽出
  for (let l = 0; l < lines.length; l++) {
    let line = lines[l].trim();

    // パターンA: Kindleなど「商品名: 〇〇」
    if (line.match(/^商品名\s*[:：]/)) {
       let title = line.replace(/^商品名\s*[:：]/, '').replace(/\(Kindle版\)/gi, '').trim();
       if (title && orderedTitles.indexOf(title) === -1) orderedTitles.push(title);
       continue;
    }

    // パターンB: 紙の本など、次の行付近に「数量: 1」や「販売:」がある
    if (line.match(/^数量\s*[:：]\s*\d+/) || line.match(/^販売\s*[:：]/)) {
       // 1〜3行上を遡ってタイトルを探す
       for (let prev = l - 1; prev >= Math.max(0, l - 3); prev--) {
         let prevLine = lines[prev].trim();
         // 記号だけの行や空行は無視
         if (prevLine && !prevLine.match(/^[=\-]+$/) && prevLine.indexOf('商品名') === -1) {
           if (orderedTitles.indexOf(prevLine) === -1) orderedTitles.push(prevLine);
           break;
         }
       }
    }
  }

  // どうしても抽出できなかった場合のフォールバック（件名から抽出）
  if (orderedTitles.length === 0) {
     let subj = msg.getSubject();
     let m1 = subj.match(/注文済み:\s*「(.*?)」/);
     if (m1) orderedTitles.push(m1[1]);
     else {
       let m2 = subj.match(/ご注文:\s*(.*?)(?:\(|とさらに|$)/);
       if (m2) orderedTitles.push(m2[1].trim());
     }
  }

  Logger.log("Amazonメールを処理: " + msg.getSubject());

  // 抽出した各タイトルについて、HTMLから対応するASINを探す
  for (let t = 0; t < orderedTitles.length; t++) {
    let title = orderedTitles[t];
    let asin = '';

    // HTML本文内でタイトルの位置を探し、その直前にあるASINを抽出する
    // （タイトルが一部省略されている場合を考慮し、最初の10文字程度で検索）
    let searchStr = title.length > 10 ? title.substring(0, 10) : title;
    // 特殊記号をエスケープ
    searchStr = searchStr.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

    let titleRegex = new RegExp('(?:dp|product|ASIN)(?:\\/|%2F)([A-Z0-9]{10}).{0,300}' + searchStr, 'i');
    let match = htmlBody.match(titleRegex);
    if (match) {
       asin = match[1];
    }

    if (asin.match(/^4[0-9]{9}$/)) {
      Logger.log(" -> 紙の本を抽出: " + title + " (ASIN: " + asin + ")");
      books.push({ isbn: convertIsbn10To13(asin), title: title, isAmazonB0: false });
    } else if (asin.match(/^B0/)) {
      Logger.log(" -> KindleまたはAmazon商品を抽出: " + title + " (ASIN: " + asin + ")");
      books.push({ isbn: '', title: title, isAmazonB0: true });
    } else {
      // ASINが見つからなかったがタイトルはある場合（Kindleの可能性あり）
      Logger.log(" -> ASIN未検出ですがタイトルを抽出: " + title);
      books.push({ isbn: '', title: title, isAmazonB0: true });
    }
  }
}

