// 比較用に全角半角や空白などの表記揺れをなくした文字列を生成する
function normalizeTitle(title) {
  if (!title) return '';
  return title
    .replace(/[（）]/g, function(m) { return m === '（' ? '(' : ')'; }) // 全角括弧を半角に
    .replace(/[　\s]/g, '') // 全角半角の空白を削除
    .replace(/[！!？?]/g, '') // 感嘆符や疑問符を削除
    .toLowerCase(); // 英字を小文字に
}

