392: function getAmazonCoverUrl(isbn13) {
393:     if (!isbn13) return '';
394:     let asin = isbn13;
395:     if (isbn13.startsWith('978') && isbn13.length === 13) {
396:         const base = isbn13.substring(3, 12);
397:         let sum = 0;
398:         for (let i = 0; i < 9; i++) {
399:             sum += parseInt(base[i]) * (10 - i);
400:         }
401:         const check = 11 - (sum % 11);
402:         const checkDigit = check === 10 ? 'X' : (check === 11 ? '0' : check.toString());
403:         asin = base + checkDigit;
404:     }
405:     return `https://images-na.ssl-images-amazon.com/images/P/${asin}.09.LZZZZZZZ.jpg`;
