252:                             const info = gbData.items[0].volumeInfo;
253:                             title = info.title || "";
254:                             author = info.authors ? info.authors.join(", ") : "";
255:                             publisher = info.publisher || "";
256:                             year = normalizeDate(info.publishedDate || "");
257:                             officialDescription = info.description || "";
258:                         }
