421: function sendToGas(title, author, isbn, publisher, year, status, officialDescription = "") {
422:     // UIを隠して送信中メッセージを表示
423:     document.getElementById('confirmDetails').style.display = 'none';
424:     document.getElementById('scanResult').innerText = `【${title}】\nスプレッドシートへ送信中...`;
425:     
426:     // GAS Web Appに送信
427:     const gasUrl = localStorage.getItem('gasWebAppUrl');
428:     if(!gasUrl) {
429:         document.getElementById('scanResult').innerText = 'エラー: 設定画面から「GAS WebアプリのURL」を保存してください！';
430:         return;
431:     }
432:     
433:     // スマホブラウザのセキュリティ（ITPやCORSブロック）を完全に回避するため、
434:     // fetchではなく見えないフォーム（iframe）を使ってPOST送信する
435:     if (!document.getElementById('hidden_iframe')) {
436:         const iframe = document.createElement('iframe');
437:         iframe.name = 'hidden_iframe';
438:         iframe.id = 'hidden_iframe';
439:         iframe.style.display = 'none';
440:         document.body.appendChild(iframe);
441:     }
442:     
443:     const form = document.createElement('form');
444:     form.method = 'POST';
445:     form.action = gasUrl;
446:     form.target = 'hidden_iframe';
447:     
448:     const fields = { title, author, isbn, status, publisher, year, description: officialDescription };
449:     for (let key in fields) {
450:         if (fields[key]) {
451:             const input = document.createElement('input');
452:             input.type = 'hidden';
453:             input.name = key;
454:             input.value = fields[key];
455:             form.appendChild(input);
456:         }
457:     }
458:     
459:     document.body.appendChild(form);
460:     form.submit();
461:     document.body.removeChild(form);
462:     
463:     // 送信は一瞬で終わるので完了メッセージを表示
464:     document.getElementById('scanResult').innerText = `追加完了: ${title}\n\n(画面を更新します)`;
465:     
466:     // Googleスプレッドシートの「ウェブに公開(CSV)」は、Google側のサーバー仕様で
467:     // 反映までに最大5分ほどのタイムラグが発生します。
468:     // その遅延をごまかすため、画面上（メモリ上）だけ先に本を追加して表示します。
469:     const newBook = {
470:         Title: title,
471:         Author: author,
472:         Status: status,
473:         Gemini_Summary: "",
474:         Tags: ""
475:     };
476:     
477:     setTimeout(() => {
478:         document.getElementById('scannerModal').classList.remove('show');
479:         document.getElementById('scanResult').innerText = "";
480:         
481:         // メモリ上の配列の先頭（新着順）に追加して再描画
482:         allBooks.unshift(newBook);
483:         renderBooks(allBooks);
484:         
485:         // 裏で一応CSVの再取得もリクエストしておく
486:         const sheetUrl = localStorage.getItem('sheetCsvUrl');
487:         if (sheetUrl) fetchDataFromUrl(sheetUrl);
488:     }, 3000);
489: }
