535: function fetchDataFromUrl(url) {
536:     document.getElementById('bookGrid').innerHTML = '<div class="empty-state"><p>データを読み込み中...</p></div>';
537:     
538:     if (url.includes('/edit')) {
539:         document.getElementById('bookGrid').innerHTML = '<div class="empty-state" style="color: #fca5a5;"><p>⚠️ エラー: URLが間違っています</p><p class="sub-text">ブラウザの上のURL（/edit...）ではなく、「ファイル」＞「共有」＞「ウェブに公開」で発行された <strong>/pub?output=csv</strong> で終わるURLを入力してください。</p></div>';
540:         return;
541:     }
542: 
543:     if (url.includes('/pubhtml')) {
544:         url = url.replace('/pubhtml', '/pub');
545:         if (!url.includes('output=csv')) {
546:             url += url.includes('?') ? '&output=csv' : '?output=csv';
547:         }
548:     }
549:     
550:     // キャッシュ回避のためのパラメータを追加
551:     const fetchUrl = url + (url.includes('?') ? '&' : '?') + 't=' + new Date().getTime();
552: 
553:     fetch(fetchUrl, { cache: 'no-store' })
554:         .then(response => {
555:             if (!response.ok) throw new Error(`HTTPエラー ${response.status}`);
556:             return response.text();
557:         })
558:         .then(csvText => {
559:             if (csvText.trim().startsWith('<!DOCTYPE') || csvText.trim().startsWith('<html')) {
560:                 throw new Error('CSVではなくウェブページが返されました。「ウェブページ」ではなく「CSV」形式で公開されているか確認してください。');
561:             }
562:             
563:             Papa.parse(csvText, {
564:                 header: true,
565:                 skipEmptyLines: true,
566:                 complete: function(results) {
567:                     // 全データに対して最新の自動整形（著者名・日付など）を適用
568:                     results.data.forEach(book => {
569:                         if (book.Author) book.Author = cleanAuthorName(book.Author);
570:                         if (book.Title) book.Title = book.Title.trim();
571:                         if (book.Year) book.Year = normalizeDate(book.Year);
572:                     });
573: 
574:                     // 新着順にするために配列を反転
575:                     allBooks = results.data.reverse();
576:                     renderBooks(allBooks);
577:                 },
578:                 error: function(err) {
579:                     throw new Error('CSVの解析に失敗しました: ' + err.message);
580:                 }
581:             });
582:         })
583:         .catch(err => {
584:             let errorMsg = err.message;
585:             if (errorMsg === 'Failed to fetch' || errorMsg.includes('NetworkError')) {
586:                 errorMsg = 'ネットワークエラーが発生しました。URLが正しいか、セキュリティでブロックされていないか確認してください。';
587:             }
588:             document.getElementById('bookGrid').innerHTML = `<div class="empty-state" style="color: #fca5a5;"><p>⚠️ エラーが発生しました: ${errorMsg}</p></div>`;
589:         });
590: }
