603: function renderBooks(books) {
604:     const grid = document.getElementById('bookGrid');
605:     grid.innerHTML = '';
606: 
607:     if (books.length === 0) {
608:         grid.innerHTML = '<div class="empty-state"><p>本が見つかりません</p></div>';
609:         return;
610:     }
611: 
612:     books.forEach(book => {
613:         if (!book.Title) return;
614: 
615:         const card = document.createElement('div');
616:         card.className = 'book-card';
617: 
618:         let tagsHtml = '';
619:         if (book.Status) {
620:             let displayStatus = book.Status;
621:             if (displayStatus === '読書中') displayStatus = 'いま読んでる';
622:             
623:             let bg = 'rgba(56, 189, 248, 0.2)';
624:             let color = '#7dd3fc';
625:             if (displayStatus === '読み終わった') { bg = 'rgba(52, 211, 153, 0.2)'; color = '#6ee7b7'; }      // 緑系
626:             else if (displayStatus === 'いま読んでる') { bg = 'rgba(56, 189, 248, 0.2)'; color = '#7dd3fc'; } // 青系
627:             else if (displayStatus === '積読') { bg = 'rgba(251, 191, 36, 0.2)'; color = '#fcd34d'; }        // 黄系
628:             else if (displayStatus === '読みたい') { bg = 'rgba(192, 132, 252, 0.2)'; color = '#d8b4fe'; }    // 紫系
629:             else if (displayStatus === '手放した') { bg = 'rgba(156, 163, 175, 0.2)'; color = '#d1d5db'; }    // 灰系
630:             
631:             tagsHtml += `<span class="tag" style="background: ${bg}; color: ${color};">${displayStatus}</span>`;
632:         }
633: 
634:         // 書影のURL。精度の高いAmazon(ASIN)をメインにし、失敗したらOpenBDにフォールバック
635:         const amazonUrl = getAmazonCoverUrl(book.ISBN13);
636:         const openbdUrl = `https://cover.openbd.jp/${book.ISBN13}.jpg`;
637:         
638:         // どちらも失敗した場合は非表示にする
639:         const fallbackScript = `this.onerror=null; this.src='${openbdUrl}'; this.onerror=function(){this.style.display='none';}`;
640:         const onloadScript = `if(this.naturalWidth <= 1) { this.onload=null; this.src='${openbdUrl}'; }`;
641:         const coverUrl = book.ISBN13 ? amazonUrl : 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
642:         // 背景色を透明にすることで、Amazonの1x1透明GIFが返ってきた場合でも下のテキストが見えるようにする
643:         const imgTag = book.ISBN13 ? `<img src="${amazonUrl}" alt="書影" style="width: 100%; height: 100%; object-fit: cover; box-shadow: 0 4px 6px rgba(0,0,0,0.3); position: relative; z-index: 1; background: transparent;" onload="${onloadScript}" onerror="${fallbackScript}">` : '';
644: 
645:         // 書影を表示するためのフレックスレイアウトを追加
646:         
647:         let pubInfo = [];
648:         if (book.Publisher) pubInfo.push(String(book.Publisher).trim());
649:         if (book.Year) {
650:             let cleanYear = String(book.Year).replace(/\r/g, '').replace(/年/g, '').trim();
651:             if (cleanYear) {
652:                 let parts = cleanYear.split('-');
653:                 if (parts.length === 3) {
654:                     cleanYear = `${parseInt(parts[0], 10)}年${parseInt(parts[1], 10)}月${parseInt(parts[2], 10)}日`;
655:                 } else if (parts.length === 2) {
656:                     cleanYear = `${parseInt(parts[0], 10)}年${parseInt(parts[1], 10)}月`;
657:                 } else if (parts.length === 1 && cleanYear.match(/^\d{4}$/)) {
658:                     cleanYear = `${cleanYear}年`;
659:                 }
660:                 pubInfo.push(cleanYear);
661:             }
662:         }
663:         let pubInfoHtml = pubInfo.map(escapeHtml).join('<br>');
664: 
665:         card.innerHTML = `
666:             <div style="flex-shrink: 0; width: 80px; position: relative; background: #1e293b; border-radius: 4px; overflow: hidden; display: flex; align-items: center; justify-content: center; min-height: 115px;" class="cover-wrapper">
667:                 <span style="position: absolute; font-size: 0.65em; color: #cbd5e1; text-align: center; padding: 4px; line-height: 1.3; word-break: break-all; z-index: 0;">${escapeHtml(book.Title)}</span>
668:                 ${imgTag}
669:             </div>
670:             <div style="flex-grow: 1; min-width: 0; display: flex; flex-direction: column;" class="book-details">
671:                 <div class="book-title">${escapeHtml(book.Title)}</div>
672:                 <div class="book-author" style="margin-bottom: 4px;">${escapeHtml(book.Author || '著者不明')}</div>
673:                 <div class="book-publisher" style="font-size: 0.8em; color: #94a3b8; line-height: 1.4;">${pubInfoHtml}</div>
674:                 <div style="flex-grow: 1;"></div>
675:                 <div class="book-tags" style="margin-top: 8px;">${tagsHtml}</div>
676:             </div>
677:         `;
678:         
679:         // カードクリックで詳細モーダルを開く
680:         card.addEventListener('click', () => {
681:             openDetailModal(book, coverUrl);
682:         });
683: 
684:         grid.appendChild(card);
685:     });
686: }
