302: function cleanAuthorName(authorStr) {
303:     if (!authorStr) return "";
304:     
305:     // 1. 役割や生没年を削除
306:     authorStr = authorStr.replace(/[\/／\s\[\(]*?(著|編|訳|原作|作画|原案)[\]\)]?/g, '');
