315:     // 4. First Pass Last, First Merger (NDL対策)
316:     const replacer = (match, p1, p2, p3, p4) => {
317:         let last = p2;
318:         let first = p3;
319:         let kanjiMatch = last.match(/[\u4E00-\u9FFF]/g);
320:         let kanjiCount = kanjiMatch ? kanjiMatch.length : 0;
321:         if (kanjiCount <= 2 && last.length <= 4) {
322:             return p1 + last + first;
323:         }
324:         return match;
325:     };
326:     
327:     // 先読みアサーション (?=$|[\s\/／・,]) を使用して、再帰的結合を防止
328:     let regex = /(^|[\s\/／・])([\u4E00-\u9FFF\u3040-\u309F\u30A0-\u30FFA-Za-z]{1,4})\s*,\s*([\u4E00-\u9FFF\u3040-\u309F\u30A0-\u30FFA-Za-z]{1,4}[^\s,]*)(?=$|[\s\/／・,])/g;
329:     authorStr = authorStr.replace(regex, replacer);
330:     
331:     // 5. 残ったスペースと読点をカンマに変換（複数著者の区切り）
332:     authorStr = authorStr.replace(/[\s、，]+/g, ', ');
333:     
334:     // 6. 保護した英語スペースを戻す
